import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.C5oN-8Wt.js";const o="/cns_master_docs/teaching-v0.3.0-alpha/08-fm.svg",g=JSON.parse('{"title":"08 把一个值变成转动速度：基础调频与解调","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/learn/08-fm/index.md","filePath":"v0.3.0-alpha/learn/08-fm/index.md"}'),s={name:"v0.3.0-alpha/learn/08-fm/index.md"};function n(l,t,i,p,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="_08-把一个值变成转动速度-基础调频与解调" tabindex="-1">08 把一个值变成转动速度：基础调频与解调 <a class="header-anchor" href="#_08-把一个值变成转动速度-基础调频与解调" aria-label="Permalink to &quot;08 把一个值变成转动速度：基础调频与解调&quot;">​</a></h1><p>通信要把信息放进某种信号特征，接收端再从那个特征估计信息。本课从最简单的情况开始：把恒定数值 <strong>1</strong> 变成复数点的转动速度，再通过相邻采样点的相位变化恢复这个数。</p><p>适用 CNS Master <strong>v0.3.0-alpha</strong>。先完成<a href="./../07-iq/">07 I/Q 与圆周上的点</a>。数值 1 只是归一化输入，不把它直接当成高度、速度或定位结果。</p><p><a href="../../../downloads/teaching-v0.3.0-alpha/08-fm.cnsproj" download>下载本课工程：08-fm.cnsproj</a></p><h2 id="目标与前置概念" tabindex="-1">目标与前置概念 <a class="header-anchor" href="#目标与前置概念" aria-label="Permalink to &quot;目标与前置概念&quot;">​</a></h2><p><strong>调制</strong>是让信息控制信号的某种特征；本课的<strong>调频</strong>让输入数控制相位转动的速度。<strong>解调</strong>是从变化的特征估计输入。这里不需要先学完整的无线电发送机，只需记住：一圈是 <code>2π rad</code>，采样率是每秒走多少步。</p><p>本课要分清三种数：输入值、频率（Hz）和相位增量（rad/采样）。它们通过参数换算，不能直接互换单位。</p><h2 id="接线与参数理由" tabindex="-1">接线与参数理由 <a class="header-anchor" href="#接线与参数理由" aria-label="Permalink to &quot;接线与参数理由&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号源 1（常量 1）.out ──→ 调频 1.in</span></span>
<span class="line"><span>                              out ──→ 正交解调 1.in ──→ 恢复值</span></span>
<span class="line"><span>                               └──→ 幅相分解 1.in</span></span>
<span class="line"><span>                                       ├─ magnitude：幅度</span></span>
<span class="line"><span>                                       └─ phase：相位（rad）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>位置</th><th>本课值</th><th>选择理由</th></tr></thead><tbody><tr><td>信号源 1</td><td>波形 constant；幅度 1；频率 0；偏置 0；Fs＝4096 Hz</td><td>先固定输入，容易核对转动速度与恢复值</td></tr><tr><td>调频 1</td><td>灵敏度 <code>π/8 ≈ 0.3926990817</code> rad/采样/单位输入</td><td>输入为 1 时，每步转 1/16 圈，16 步转完一圈</td></tr><tr><td>正交解调 1</td><td>相位差倍率 <code>8/π ≈ 2.5464790895</code></td><td>与调频灵敏度互为倒数，恢复原输入的数值尺度</td></tr><tr><td>幅相分解 1</td><td>无可调计算参数</td><td>把同一个复数样本的距离、方向分别输出</td></tr></tbody></table><p>所有处理保持输入采样率，因此 <code>4096 ÷ 16 = 256</code>：调频输出应为约 <strong>+256 Hz</strong> 的复数单音。灵敏度里的 <code>0.392699…</code> 不是 Hz；解调后的 <code>1</code> 也不是 1 Hz。</p><p>工程已经填入计算值。手工重建时可以用上面的十进制近似数；实际运行使用原生浮点数，不要求结果与无限精度的 π 完全一致。</p><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>下载工程，Shift+F5 停止已有任务，Ctrl+O 打开。核对信号源确实为“常量”，再核对调频灵敏度与解调倍率。</li><li>先预测：把输入从 1 变大，会让调频输出的幅度更高，还是让点转得更快？暂不改参数。</li><li>按 F5。在输入／解调的观察器参数页，确认两条捕获分别为“信号源 1 → 输出”和“正交解调 1 → 输出”。输出页采用“曲线叠加”。两路单位不同，读对应纵轴的数值，不根据屏幕高度判断相等。</li><li>在调频复数输出的观察器选择“I/Q 时域”，把全宽缩到约 <strong>0.015625 s</strong>，可看约四个 256 Hz 周期。另一个观察器捕获“调频 1 → 频谱”，查看约 +256 Hz 的主峰。</li><li>若想查看幅度与相位，另插入观察器：参数页添加“幅相分解 1 → 幅度”和“→ 相位”的捕获；在候选中核对端口分别为 <code>magnitude</code>、<code>phase</code>。两种单位分别读轴；也可以各用一个单路观察器。</li><li>若需重新绑定，在参数页输入模块名并点选候选。普通输出供时域、I/Q 或星座使用；“频谱”变量供频谱使用。复数显示只留一路捕获。</li><li>运行数秒后 Shift+F5 停止，再放大或回看数据。输入应为常量 1；解调输出的新一轮首项为 0，后续约为 1。实时显示已经滚过开头时，不能据当前窗口“没看见 0”判断首项行为。</li></ol><h2 id="图像与数值怎样联系" tabindex="-1">图像与数值怎样联系 <a class="header-anchor" href="#图像与数值怎样联系" aria-label="Permalink to &quot;图像与数值怎样联系&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.3.0-alpha/08-fm.svg"><img src="`+o+'" alt="实际 GNU 数据：输入为 1 时解调首项为 0、随后约 1；输入改为 2 后恢复值约为 2"></a></p><p>左图比较输入与解调值，右图比较输入常量改变前后的结果。调频输出怎样旋转、频谱峰怎样移动，可以在工程已绑定的 I/Q 和频谱观察器中继续查看。</p><p>调频输出的 I、Q 在约 −1 到 +1 之间变化，但幅相分解的幅度应约为 1。输入控制的是转动速度，输出包络不会按输入值成比例变高。</p><p>相位在一段范围内逐步前进，到边界后绕回，看起来像锯齿。方向绕过一圈的接缝，不代表复数幅度突然中断。相位输出只表示当前方向，没有展开成累计转过多少圈。</p><p>正交解调器比较相邻两点转过的角度，再乘以所设倍率。本例每步约转 <code>π/8</code>，所以 <code>(π/8)×(8/π)≈1</code>。新准备后没有前一个有效历史样本，原生首项为 0；它仍占正常的第一个时间位置，不应删掉它来伪造对齐。</p><h2 id="单参数对照-只把常量幅度从-1-改为-2" tabindex="-1">单参数对照：只把常量幅度从 1 改为 2 <a class="header-anchor" href="#单参数对照-只把常量幅度从-1-改为-2" aria-label="Permalink to &quot;单参数对照：只把常量幅度从 1 改为 2&quot;">​</a></h2><ol><li>停止，只将信号源 1 的“幅度”改为 <strong>2</strong>。波形、偏置、Fs、灵敏度、解调倍率均不改变。</li><li>重新按 F5。查看调频输出频谱：主峰应变为约 <strong>+512 Hz</strong>；输出幅度仍约为 1。</li><li>查看解调输出：首项仍为 0，随后约为 <strong>2</strong>。在相同的时域范围中，I/Q 的周期数增加。</li><li>恢复常量幅度 1，重新运行，记录两轮“输入值—频谱峰值—解调值”的对应关系。</li></ol><p>本课始终让每步转角小于半圈。相邻样本只能确定一段范围内的转角；若一步跨过太多角度，就会出现方向和速度的歧义，单纯把解调倍率调大无法修复。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查方法</th></tr></thead><tbody><tr><td>输入变为 2，复数幅度没有翻倍</td><td>这是本例调频的预期行为；请检查转动速度或频谱位置</td></tr><tr><td>解调结果约为 0.3927</td><td>可能仍使用倍率 1；核对本课为 8/π</td></tr><tr><td>相位突然向下跳</td><td>可能是主值绕回；同时检查幅度是否仍约为 1</td></tr><tr><td>两条平线重合，却读数不同</td><td>输入与解调值使用不同单位，须读各自轴；位置相同不自动证明数值相等</td></tr><tr><td>改了草稿，图像未变</td><td>本课统一停止后重新运行；只编辑属性不代表已对当前任务在线应用</td></tr></tbody></table><p>本例没有加入噪声、频偏、定时偏差、无线电硬件或传输网络。它验证理想条件下的调制／解调数值关系，不构成真实遥测链路。下一课研究另一条路线：<a href="./../09-symbols/">把数据编号映射成离散的 I/Q 点</a>。</p><p>模块参考：<a href="./../../modules/frequency_modulator/">调频</a> · <a href="./../../modules/quadrature_demod/">正交解调</a> · <a href="./../../modules/magphase_split/">幅相分解</a> · <a href="./../">返回学习路径</a></p>',27)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
